# ---------------------------------------------------------------- assemble
import random as _random


def _shuffled(options, correct, seed):
    rng = _random.Random(seed)
    order = list(range(len(options)))
    rng.shuffle(order)
    new_options = [options[i] for i in order]
    if isinstance(correct, list):
        return new_options, sorted(order.index(c) for c in correct)
    return new_options, order.index(correct)


QUESTIONS = []
for _i, (_cat, _q, _opts, _correct, _expl) in enumerate(_QS['mc'], 1):
    _o, _c = _shuffled(_opts, _correct, 1000 + _i)
    QUESTIONS.append({'id': f'q{_i}', 'cat': _cat, 'type': 'mc', 'question': _q, 'options': _o, 'correct': _c, 'explanation': _expl})
for _i, (_cat, _q, _opts, _correct, _expl) in enumerate(_QS['ms'], 1):
    _o, _c = _shuffled(_opts, _correct, 2000 + _i)
    QUESTIONS.append({'id': f'msq{_i}', 'cat': _cat, 'type': 'ms', 'question': _q, 'options': _o, 'correct': _c, 'explanation': _expl})
for _i, (_cat, _q, _ans, _expl) in enumerate(_QS['tf'], 1):
    QUESTIONS.append({'id': f'tf{_i}', 'cat': _cat, 'type': 'tf', 'question': _q, 'answer': _ans, 'explanation': _expl})


