def _extend_lesson(lesson_id, paragraphs, terms, traps):
    les = _LESSON_BY_ID[lesson_id]
    les['reading'] = les['reading'].rstrip() + ''.join('\n\n' + p for p in paragraphs)
    les['keyTerms'] = list(les['keyTerms']) + terms
    les['commonTraps'] = list(les['commonTraps']) + traps


